// Três histórias A1-A2 (português do Brasil, traduções em inglês): 10 cenas por história, escolhas e três finais.
window.VB_HIST=window.VB_HIST||{};VB_HIST.pt=[{"id":"ultima-partida","titulo":"The Last Departure","genero":"Viagem","nivel":"A1–A2","desc":"An undated ticket and a changed timetable at Luz Station in São Paulo.","inicio":"c1","cenas":{"c1":{"cap":"The first sign","p":[["Você chega à Estação da Luz às seis da manhã. Na bolsa, você leva uma passagem para Jundiaí, mas o bilhete não tem data. Perto da porta, um homem de terno parece muito preocupado. Pelo alto-falante, uma voz avisa que o horário mudou. O relógio mostra que falta pouco tempo.","You arrive at Luz Station at six in the morning. In your bag, you carry a ticket to Jundiaí, but the ticket has no date. Near the door, a man in a suit looks very worried. Over the loudspeaker, a voice announces that the timetable has changed. The clock shows that there's little time left.",[["Você chega à Estação da Luz","You arrive at Luz Station","você|chegar|à|estação"],["às seis da manhã.","at six in the morning.","da|manhã"],["Na bolsa, você leva","In your bag, you carry","na|bolsa|você|levar"],["uma passagem para Jundiaí,","a ticket to Jundiaí,","uma|passagem|para"],["mas o bilhete não tem data.","but the ticket has no date.","mas|o|bilhete|não|ter|data"],["Perto da porta,","Near the door,","perto|da|porta"],["um homem de terno","a man in a suit","um|homem|de"],["parece muito preocupado.","looks very worried.","parecer|muito|preocupar"],["Pelo alto-falante,","Over the loudspeaker,","pelo"],["uma voz avisa que o horário mudou.","a voice announces that the timetable has changed.","uma|voz|que|o|mudar"],["O relógio mostra","The clock shows","o|relógio|mostrar"],["que falta pouco tempo.","that there's little time left.","que|pouco|tempo"]]]],"escolhas":[{"fl":"Perguntar a uma funcionária da estação.","pt":"Ask a station worker.","ir":"c2a"},{"fl":"Procurar informações sozinho.","pt":"Look for information on your own.","ir":"c2b"}]},"c2a":{"cap":"The conversation","p":[["Você se aproxima de uma funcionária no balcão. O nome dela é dona Cida. Ela escuta a sua pergunta, mas não responde logo. Você explica que a passagem não tem data. Ela olha para os lados e aponta um corredor à esquerda. Parece que ela sabe algo e não quer dizer na frente dos outros.","You go up to a worker at the counter. Her name is Dona Cida. She listens to your question, but doesn't answer right away. You explain that the ticket has no date. She looks around and points to a corridor on the left. It seems she knows something and doesn't want to say it in front of the others.",[["Você se aproxima","You go up","você|se"],["de uma funcionária no balcão.","to a worker at the counter.","de|uma|no"],["O nome dela é dona Cida.","Her name is Dona Cida.","o|nome|dela|ser"],["Ela escuta a sua pergunta,","She listens to your question,","ela|escutar|a|sua|pergunta"],["mas não responde logo.","but doesn't answer right away.","mas|não|responder|logo"],["Você explica","You explain","você|explicar"],["que a passagem não tem data.","that the ticket has no date.","que|a|passagem|não|ter|data"],["Ela olha para os lados","She looks around","ela|olhar|para|os|lado"],["e aponta um corredor à esquerda.","and points to a corridor on the left.","e|um|à|esquerda"],["Parece que ela sabe algo","It seems she knows something","parecer|que|ela|saber|algo"],["e não quer dizer","and doesn't want to say it","e|não|querer|dizer"],["na frente dos outros.","in front of the others.","na|frente|dos|outro"]]]],"escolhas":[{"fl":"Ficar e escutar a explicação com atenção.","pt":"Stay and listen carefully to her explanation.","ir":"c3a"},{"fl":"Agradecer e ir até o corredor.","pt":"Thank her and go to the corridor.","ir":"c3b"}]},"c2b":{"cap":"The empty hall","p":[["Você decide procurar a resposta por conta própria. O saguão está quase vazio. Atrás de uma porta de vidro, você vê uma placa azul com uma seta. Nesse momento, o celular vibra. É uma mensagem da companhia de trem: a saída principal está fechada. A placa e a mensagem dizem coisas diferentes.","You decide to look for the answer on your own. The hall is almost empty. Behind a glass door, you see a blue sign with an arrow. At that moment, your phone vibrates. It's a message from the train company: the main exit is closed. The sign and the message say different things.",[["Você decide","You decide","você|decidir"],["procurar a resposta por conta própria.","to look for the answer on your own.","procurar|a|resposta|por|conta|próprio"],["O saguão está quase vazio.","The hall is almost empty.","o|estar|quase|vazio"],["Atrás de uma porta de vidro,","Behind a glass door,","de|uma|porta|de|vidro"],["você vê uma placa azul","you see a blue sign","você|ver|uma|azul"],["com uma seta.","with an arrow.","com|uma"],["Nesse momento,","At that moment,","em|esse|momento"],["o celular vibra.","your phone vibrates.","o|celular"],["É uma mensagem da companhia de trem:","It's a message from the train company:","ser|uma|mensagem|da|companhia|de|trem"],["a saída principal está fechada.","the main exit is closed.","a|principal|estar|fechar"],["A placa e a mensagem","The sign and the message","a|e|a|mensagem"],["dizem coisas diferentes.","say different things.","dizer|coisa|diferente"]]]],"escolhas":[{"fl":"Seguir a seta da placa azul.","pt":"Follow the arrow on the blue sign.","ir":"c3c"},{"fl":"Confiar na mensagem do celular.","pt":"Trust the message on your phone.","ir":"c3d"}]},"c3a":{"cap":"The hidden paper","p":[["Dona Cida tira do bolso um papel pequeno. Nele, você lê que a sua passagem tem outro número: o trem das seis e meia agora sai da plataforma quatro. Ela pode trocar o bilhete, mas só se você decidir agora. Atrás de você, a fila começa a crescer.","Dona Cida takes a small piece of paper out of her pocket. On it, you read that your ticket has a different number: the six-thirty train now leaves from platform four. She can change the ticket, but only if you decide now. Behind you, the line starts to grow.",[["Dona Cida tira do bolso","Dona Cida takes out of her pocket","tirar|do"],["um papel pequeno.","a small piece of paper.","um|papel|pequeno"],["Nele, você lê","On it, you read","em|ele|você|ler"],["que a sua passagem tem outro número:","that your ticket has a different number:","que|a|sua|passagem|ter|outro|número"],["o trem das seis e meia","the six-thirty train","o|trem|de|a|e|meio"],["agora sai da plataforma quatro.","now leaves from platform four.","agora|sair|da"],["Ela pode trocar o bilhete,","She can change the ticket,","ela|poder|trocar|o|bilhete"],["mas só se você decidir agora.","but only if you decide now.","mas|só|se|você|decidir|agora"],["Atrás de você,","Behind you,","de|você"],["a fila começa a crescer.","the line starts to grow.","a|fila|começar|a|crescer"]]]],"escolhas":[{"fl":"Aceitar a ajuda e conferir o bilhete novo.","pt":"Accept the help and check the new ticket.","ir":"f_good"},{"fl":"Agradecer e procurar a plataforma sozinho.","pt":"Thank her and look for the platform on your own.","ir":"f_neutral"}]},"c3b":{"cap":"The locked door","p":[["Você agradece e entra no corredor. Ele é comprido e termina numa porta trancada. Do outro lado, você ouve vozes. Alguém fala de uma placa azul e de um trem que mudou de plataforma. Você para e presta atenção. Mas o relógio não para, e você não tem tempo para tudo.","You thank her and go into the corridor. It's long and ends at a locked door. On the other side, you hear voices. Someone talks about a blue sign and about a train that changed platforms. You stop and pay attention. But the clock doesn't stop, and you don't have time for everything.",[["Você agradece","You thank her","você|agradecer"],["e entra no corredor.","and go into the corridor.","e|entrar|no"],["Ele é comprido","It's long","ele|ser"],["e termina numa porta trancada.","and ends at a locked door.","e|terminar|em|uma|porta"],["Do outro lado,","On the other side,","do|outro|lado"],["você ouve vozes.","you hear voices.","você|ouvir|voz"],["Alguém fala de uma placa azul","Someone talks about a blue sign","alguém|falar|de|uma|azul"],["e de um trem","and about a train","e|de|um|trem"],["que mudou de plataforma.","that changed platforms.","que|mudar|de"],["Você para e presta atenção.","You stop and pay attention.","você|parar|e"],["Mas o relógio não para,","But the clock doesn't stop,","mas|o|relógio|não|parar"],["e você não tem tempo para tudo.","and you don't have time for everything.","e|você|não|ter|tempo|para|tudo"]]]],"escolhas":[{"fl":"Esperar e escutar perto da porta.","pt":"Wait and listen by the door.","ir":"f_neutral"},{"fl":"Bater na porta e entrar sem pensar.","pt":"Knock on the door and go in without thinking.","ir":"f_bad"}]},"c3c":{"cap":"Someone knows","p":[["Você segue a seta e chega a uma sala pequena. Ao lado de uma janela aberta, um senhor de uniforme toma café. É o chefe da estação. Ele olha a sua passagem e sorri: sabe exatamente qual é o problema. Mas antes, quer saber por que você estava numa área só para funcionários.","You follow the arrow and reach a small room. Next to an open window, a man in uniform is drinking coffee. He's the station master. He looks at your ticket and smiles: he knows exactly what the problem is. But first, he wants to know why you were in a staff-only area.",[["Você segue a seta","You follow the arrow","você|seguir|a"],["e chega a uma sala pequena.","and reach a small room.","e|chegar|a|uma|sala|pequeno"],["Ao lado de uma janela aberta,","Next to an open window,","ao|lado|de|uma|janela|aberto"],["um senhor de uniforme toma café.","a man in uniform is drinking coffee.","um|senhor|de|tomar|café"],["É o chefe da estação.","He's the station master.","ser|o|chefe|da|estação"],["Ele olha a sua passagem e sorri:","He looks at your ticket and smiles:","ele|olhar|a|sua|passagem|e|sorrir"],["sabe exatamente qual é o problema.","he knows exactly what the problem is.","saber|exatamente|qual|ser|o|problema"],["Mas antes, quer saber","But first, he wants to know","mas|antes|querer|saber"],["por que você estava","why you were","por|que|você|estar"],["numa área só para funcionários.","in a staff-only area.","em|uma|área|só|para"]]]],"escolhas":[{"fl":"Dizer a verdade e pedir ajuda.","pt":"Tell the truth and ask for help.","ir":"f_good"},{"fl":"Inventar uma desculpa e ir embora.","pt":"Make up an excuse and leave.","ir":"f_bad"}]},"c3d":{"cap":"The message","p":[["Você lê a mensagem mais uma vez. Ela diz claramente: saída principal fechada, use a entrada lateral. Mas a entrada lateral fica do outro lado da rua, e está chovendo. Por um momento, você pensa em desistir e voltar para casa. Então lembra da reunião em Jundiaí às nove. Você ainda quer pegar esse trem.","You read the message one more time. It says clearly: main exit closed, use the side entrance. But the side entrance is on the other side of the street, and it's raining. For a moment, you think about giving up and going back home. Then you remember the meeting in Jundiaí at nine. You still want to catch that train.",[["Você lê a mensagem","You read the message","você|ler|a|mensagem"],["mais uma vez.","one more time.","mais|uma|vez"],["Ela diz claramente:","It says clearly:","ela|dizer"],["saída principal fechada,","main exit closed,","principal|fechar"],["use a entrada lateral.","use the side entrance.","usar|a|entrada"],["Mas a entrada lateral","But the side entrance","mas|a|entrada"],["fica do outro lado da rua,","is on the other side of the street,","ficar|do|outro|lado|da|rua"],["e está chovendo.","and it's raining.","e|estar"],["Por um momento,","For a moment,","por|um|momento"],["você pensa em desistir","you think about giving up","você|pensar|em"],["e voltar para casa.","and going back home.","e|voltar|para|casa"],["Então lembra da reunião","Then you remember the meeting","então|lembrar|da|reunião"],["em Jundiaí às nove.","in Jundiaí at nine.","em"],["Você ainda quer pegar esse trem.","You still want to catch that train.","você|ainda|querer|pegar|esse|trem"]]]],"escolhas":[{"fl":"Parar, respirar e fazer outro plano.","pt":"Stop, breathe and make another plan.","ir":"f_neutral"},{"fl":"Ignorar o aviso e correr para a plataforma.","pt":"Ignore the warning and run to the platform.","ir":"f_bad"}]},"f_good":{"cap":"Platform four","p":[["Com o bilhete novo na mão, você desce até a plataforma quatro. O trem já está lá, com as portas abertas. Você entra, encontra um lugar perto da janela e respira fundo. Às seis e meia em ponto, o trem sai. Você aprende uma coisa simples: pedir ajuda não é fraqueza.","With the new ticket in your hand, you go down to platform four. The train is already there, with its doors open. You get on, find a seat by the window and take a deep breath. At six thirty sharp, the train leaves. You learn something simple: asking for help isn't weakness.",[["Com o bilhete novo na mão,","With the new ticket in your hand,","com|o|bilhete|novo|na|mão"],["você desce até a plataforma quatro.","you go down to platform four.","você|até|a"],["O trem já está lá,","The train is already there,","o|trem|já|estar|lá"],["com as portas abertas.","with its doors open.","com|as|porta|aberto"],["Você entra,","You get on,","você|entrar"],["encontra um lugar perto da janela","find a seat by the window","encontrar|um|lugar|perto|da|janela"],["e respira fundo.","and take a deep breath.","e|fundo"],["Às seis e meia em ponto,","At six thirty sharp,","e|meio|em|ponto"],["o trem sai.","the train leaves.","o|trem|sair"],["Você aprende uma coisa simples:","You learn something simple:","você|aprender|uma|coisa|simples"],["pedir ajuda não é fraqueza.","asking for help isn't weakness.","pedir|ajuda|não|ser"]]]],"fim":{"tipo":"bom","titulo":"The right train"}},"f_neutral":{"cap":"Another chance","p":[["Você descobre parte da resposta, mas não tudo. Quando chega à plataforma certa, o trem das seis e meia acabou de sair. O próximo é só às sete e quinze. Você liga para o cliente em Jundiaí e explica a situação. Ele não fica feliz, mas aceita esperar. Nem todo final é perfeito.","You find out part of the answer, but not all of it. When you get to the right platform, the six-thirty train has just left. The next one is only at seven fifteen. You call the client in Jundiaí and explain the situation. He isn't happy, but agrees to wait. Not every ending is perfect.",[["Você descobre parte da resposta,","You find out part of the answer,","você|descobrir|parte|da|resposta"],["mas não tudo.","but not all of it.","mas|não|tudo"],["Quando chega à plataforma certa,","When you get to the right platform,","quando|chegar|à|certo"],["o trem das seis e meia","the six-thirty train","o|trem|de|a|e|meio"],["acabou de sair.","has just left.","acabar|de|sair"],["O próximo é só às sete e quinze.","The next one is only at seven fifteen.","o|próximo|ser|só|e"],["Você liga para o cliente em Jundiaí","You call the client in Jundiaí","você|ligar|para|o|cliente|em"],["e explica a situação.","and explain the situation.","e|explicar|a|situação"],["Ele não fica feliz,","He isn't happy,","ele|não|ficar|feliz"],["mas aceita esperar.","but agrees to wait.","mas|aceitar|esperar"],["Nem todo final é perfeito.","Not every ending is perfect.","nem|todo|final|ser|perfeito"]]]],"fim":{"tipo":"neutro","titulo":"The next train"}},"f_bad":{"cap":"A hard lesson","p":[["Você decide rápido demais e perde um detalhe importante. Corre para a plataforma errada e espera dez minutos. Quando um guarda olha o seu bilhete, já é tarde: o seu trem saiu da plataforma quatro. Hoje você não vai chegar a Jundiaí a tempo. Mas da próxima vez, vai conferir tudo com calma.","You decide too fast and miss an important detail. You run to the wrong platform and wait ten minutes. When a guard looks at your ticket, it's already too late: your train left from platform four. Today you won't get to Jundiaí on time. But next time, you'll check everything calmly.",[["Você decide rápido demais","You decide too fast","você|decidir|rápido|demais"],["e perde um detalhe importante.","and miss an important detail.","e|perder|um|importante"],["Corre para a plataforma errada","You run to the wrong platform","correr|para|a|errado"],["e espera dez minutos.","and wait ten minutes.","e|esperar|minuto"],["Quando um guarda olha o seu bilhete,","When a guard looks at your ticket,","quando|um|guarda|olhar|o|seu|bilhete"],["já é tarde:","it's already too late:","já|ser|tarde"],["o seu trem saiu da plataforma quatro.","your train left from platform four.","o|seu|trem|sair|da"],["Hoje você não vai chegar","Today you won't get","hoje|você|não|ir|chegar"],["a Jundiaí a tempo.","to Jundiaí on time.","a|tempo"],["Mas da próxima vez,","But next time,","mas|da|próximo|vez"],["vai conferir tudo com calma.","you'll check everything calmly.","ir|tudo|com|calmo"]]]],"fim":{"tipo":"ruim","titulo":"The empty platform"}}}},{"id":"a-carta","titulo":"The Letter Without a Name","genero":"Mistério","nivel":"A1–A2","desc":"A forgotten letter at a São Paulo library raises an unexpected question.","inicio":"c1","cenas":{"c1":{"cap":"The first sign","p":[["Você chega à Biblioteca Mário de Andrade logo cedo. Na bolsa, você leva uma carta antiga sem nome, que encontrou dentro de um livro usado. Na entrada, uma bibliotecária fala baixo ao telefone. Você ouve que um documento antigo desapareceu do arquivo. Será que a sua carta tem algo a ver com isso?","You arrive at the Mário de Andrade Library first thing in the morning. In your bag, you carry an old letter with no name, which you found inside a used book. At the entrance, a librarian is speaking quietly on the phone. You hear that an old document has disappeared from the archive. Could your letter have something to do with it?",[["Você chega à Biblioteca Mário de Andrade","You arrive at the Mário de Andrade Library","você|chegar|à|biblioteca"],["logo cedo.","first thing in the morning.","logo|cedo"],["Na bolsa, você leva","In your bag, you carry","na|bolsa|você|levar"],["uma carta antiga sem nome,","an old letter with no name,","uma|carta|sem|nome"],["que encontrou dentro de um livro usado.","which you found inside a used book.","que|encontrar|dentro|de|um|livro|usado"],["Na entrada,","At the entrance,","na|entrada"],["uma bibliotecária fala baixo","a librarian is speaking quietly","uma|falar|baixo"],["ao telefone.","on the phone.","ao|telefone"],["Você ouve","You hear","você|ouvir"],["que um documento antigo","that an old document","que|um|documento"],["desapareceu do arquivo.","has disappeared from the archive.","desaparecer|do"],["Será que a sua carta","Could your letter","ser|que|a|sua|carta"],["tem algo a ver com isso?","have something to do with it?","ter|algo|a|ver|com|isso"]]]],"escolhas":[{"fl":"Falar com a bibliotecária.","pt":"Talk to the librarian.","ir":"c2a"},{"fl":"Investigar sozinho.","pt":"Investigate on your own.","ir":"c2b"}]},"c2a":{"cap":"The conversation","p":[["Você espera a bibliotecária desligar e se apresenta. Ela se chama Helena e trabalha ali há vinte anos. Quando vê a carta, fica pálida, mas não diz nada. Depois aponta um corredor tranquilo à esquerda, onde ficam os documentos raros. Há algo importante que ela ainda não quer contar.","You wait for the librarian to hang up and introduce yourself. Her name is Helena, and she has worked there for twenty years. When she sees the letter, she turns pale, but says nothing. Then she points to a quiet corridor on the left, where the rare documents are kept. There's something important that she doesn't want to tell yet.",[["Você espera a bibliotecária desligar","You wait for the librarian to hang up","você|esperar|a|desligar"],["e se apresenta.","and introduce yourself.","e|se|apresentar"],["Ela se chama Helena","Her name is Helena","ela|se|chamar"],["e trabalha ali há vinte anos.","and she has worked there for twenty years.","e|trabalhar|ali|haver|ano"],["Quando vê a carta,","When she sees the letter,","quando|ver|a|carta"],["fica pálida,","she turns pale,","ficar"],["mas não diz nada.","but says nothing.","mas|não|dizer|nada"],["Depois aponta um corredor tranquilo","Then she points to a quiet corridor","depois|um"],["à esquerda,","on the left,","à|esquerda"],["onde ficam os documentos raros.","where the rare documents are kept.","onde|ficar|os|documento"],["Há algo importante","There's something important","haver|algo|importante"],["que ela ainda não quer contar.","that she doesn't want to tell yet.","que|ela|ainda|não|querer|contar"]]]],"escolhas":[{"fl":"Pedir que Helena explique tudo.","pt":"Ask Helena to explain everything.","ir":"c3a"},{"fl":"Agradecer e ir até o corredor.","pt":"Thank her and go to the corridor.","ir":"c3b"}]},"c2b":{"cap":"The reading room","p":[["Você decide procurar respostas por conta própria. A sala de leitura está quase vazia. Atrás de uma porta de vidro, você vê um bilhete escrito com tinta azul, a mesma tinta da sua carta. Nesse momento, o celular vibra. É uma mensagem automática: a biblioteca fecha em dez minutos.","You decide to look for answers on your own. The reading room is almost empty. Behind a glass door, you see a note written in blue ink, the same ink as your letter. At that moment, your phone vibrates. It's an automatic message: the library closes in ten minutes.",[["Você decide procurar respostas","You decide to look for answers","você|decidir|procurar|resposta"],["por conta própria.","on your own.","por|conta|próprio"],["A sala de leitura","The reading room","a|sala|de"],["está quase vazia.","is almost empty.","estar|quase|vazio"],["Atrás de uma porta de vidro,","Behind a glass door,","de|uma|porta|de|vidro"],["você vê um bilhete","you see a note","você|ver|um|bilhete"],["escrito com tinta azul,","written in blue ink,","escrever|com|tinta|azul"],["a mesma tinta da sua carta.","the same ink as your letter.","a|mesmo|tinta|da|sua|carta"],["Nesse momento,","At that moment,","em|esse|momento"],["o celular vibra.","your phone vibrates.","o|celular"],["É uma mensagem automática:","It's an automatic message:","ser|uma|mensagem"],["a biblioteca fecha em dez minutos.","the library closes in ten minutes.","a|biblioteca|fechar|em|minuto"]]]],"escolhas":[{"fl":"Abrir a porta de vidro e ler o bilhete.","pt":"Open the glass door and read the note.","ir":"c3c"},{"fl":"Obedecer à mensagem e voltar para a entrada.","pt":"Follow the message and go back to the entrance.","ir":"c3d"}]},"c3a":{"cap":"The hidden card","p":[["Helena suspira e mostra uma ficha velha do arquivo. Nela, você lê que a carta tem duas datas diferentes: uma de 1954 e outra de 1987. A carta não é o documento perdido, mas faz parte da mesma história. Helena oferece ajuda, mas só se você deixar a carta com ela por um dia.","Helena sighs and shows you an old card from the archive. On it, you read that the letter has two different dates: one from 1954 and another from 1987. The letter isn't the missing document, but it's part of the same story. Helena offers to help, but only if you leave the letter with her for a day.",[["Helena suspira e mostra","Helena sighs and shows you","e|mostrar"],["uma ficha velha do arquivo.","an old card from the archive.","uma|velho|do"],["Nela, você lê","On it, you read","em|ela|você|ler"],["que a carta tem duas datas diferentes:","that the letter has two different dates:","que|a|carta|ter|data|diferente"],["uma de 1954","one from 1954","uma|de"],["e outra de 1987.","and another from 1987.","e|outro|de"],["A carta não é o documento perdido,","The letter isn't the missing document,","a|carta|não|ser|o|documento|perder"],["mas faz parte da mesma história.","but it's part of the same story.","mas|fazer|parte|da|mesmo|história"],["Helena oferece ajuda,","Helena offers to help,","oferecer|ajuda"],["mas só se você deixar a carta","but only if you leave the letter","mas|só|se|você|deixar|a|carta"],["com ela por um dia.","with her for a day.","com|ela|por|um|dia"]]]],"escolhas":[{"fl":"Confiar em Helena e deixar a carta.","pt":"Trust Helena and leave the letter.","ir":"f_good"},{"fl":"Guardar a carta e continuar sozinho.","pt":"Keep the letter and carry on alone.","ir":"f_neutral"}]},"c3b":{"cap":"The locked door","p":[["Você agradece e segue pelo corredor. Ele é comprido e termina numa porta trancada, com uma placa: Arquivo. Do outro lado, você ouve duas vozes. Um homem fala de uma carta escrita com tinta azul e diz que precisa dela hoje. Você fica parado, com o coração acelerado.","You thank her and walk down the corridor. It's long and ends at a locked door, with a sign: Archive. On the other side, you hear two voices. A man talks about a letter written in blue ink and says he needs it today. You stand still, your heart racing.",[["Você agradece","You thank her","você|agradecer"],["e segue pelo corredor.","and walk down the corridor.","e|seguir|pelo"],["Ele é comprido","It's long","ele|ser"],["e termina numa porta trancada,","and ends at a locked door,","e|terminar|em|uma|porta"],["com uma placa: Arquivo.","with a sign: Archive.","com|uma"],["Do outro lado,","On the other side,","do|outro|lado"],["você ouve duas vozes.","you hear two voices.","você|ouvir|voz"],["Um homem fala de uma carta","A man talks about a letter","um|homem|falar|de|uma|carta"],["escrita com tinta azul","written in blue ink","escrever|com|tinta|azul"],["e diz que precisa dela hoje.","and says he needs it today.","e|dizer|que|precisar|dela|hoje"],["Você fica parado,","You stand still,","você|ficar|parar"],["com o coração acelerado.","your heart racing.","com|o|coração"]]]],"escolhas":[{"fl":"Esperar em silêncio e escutar mais.","pt":"Wait in silence and listen some more.","ir":"f_neutral"},{"fl":"Abrir a porta e mostrar a carta.","pt":"Open the door and show the letter.","ir":"f_bad"}]},"c3c":{"cap":"Someone knows","p":[["Você abre a porta de vidro e pega o bilhete. Ao lado da janela aberta, um senhor de cabelo branco está sentado com um livro. Ele vê o bilhete na sua mão e diz: “Essa letra é da minha mãe.” Ele quer saber como a carta chegou até você.","You open the glass door and take the note. Next to the open window, a white-haired man is sitting with a book. He sees the note in your hand and says: “That handwriting is my mother's.” He wants to know how the letter got to you.",[["Você abre a porta de vidro","You open the glass door","você|abrir|a|porta|de|vidro"],["e pega o bilhete.","and take the note.","e|pegar|o|bilhete"],["Ao lado da janela aberta,","Next to the open window,","ao|lado|da|janela|aberto"],["um senhor de cabelo branco","a white-haired man","um|senhor|de|cabelo|branco"],["está sentado com um livro.","is sitting with a book.","estar|sentar|com|um|livro"],["Ele vê o bilhete na sua mão","He sees the note in your hand","ele|ver|o|bilhete|na|sua|mão"],["e diz:","and says:","e|dizer"],["“Essa letra é da minha mãe.”","“That handwriting is my mother's.”","esse|ser|da|minha|mãe"],["Ele quer saber","He wants to know","ele|querer|saber"],["como a carta chegou até você.","how the letter got to you.","como|a|carta|chegar|até|você"]]]],"escolhas":[{"fl":"Contar a verdade e mostrar a carta.","pt":"Tell the truth and show the letter.","ir":"f_good"},{"fl":"Dizer que não sabe nada e sair.","pt":"Say you know nothing and leave.","ir":"f_bad"}]},"c3d":{"cap":"The message","p":[["Você volta para a entrada e lê a mensagem mais uma vez. A biblioteca fecha em dez minutos, e amanhã é feriado. Por um momento, você pensa em desistir. Mas a carta pesa na bolsa. Alguém escreveu aquelas palavras com muito amor, e você ainda quer encontrar o dono dela.","You go back to the entrance and read the message once more. The library closes in ten minutes, and tomorrow is a holiday. For a moment, you think about giving up. But the letter feels heavy in your bag. Someone wrote those words with a lot of love, and you still want to find its owner.",[["Você volta para a entrada","You go back to the entrance","você|voltar|para|a|entrada"],["e lê a mensagem mais uma vez.","and read the message once more.","e|ler|a|mensagem|mais|uma|vez"],["A biblioteca fecha em dez minutos,","The library closes in ten minutes,","a|biblioteca|fechar|em|minuto"],["e amanhã é feriado.","and tomorrow is a holiday.","e|amanhã|ser"],["Por um momento,","For a moment,","por|um|momento"],["você pensa em desistir.","you think about giving up.","você|pensar|em"],["Mas a carta pesa na bolsa.","But the letter feels heavy in your bag.","mas|a|carta|na|bolsa"],["Alguém escreveu aquelas palavras","Someone wrote those words","alguém|escrever|aquele|palavra"],["com muito amor,","with a lot of love,","com|muito|amor"],["e você ainda quer","and you still want","e|você|ainda|querer"],["encontrar o dono dela.","to find its owner.","encontrar|o|dela"]]]],"escolhas":[{"fl":"Anotar o telefone da biblioteca e voltar depois.","pt":"Write down the library's number and come back later.","ir":"f_neutral"},{"fl":"Correr de volta para o corredor.","pt":"Run back to the corridor.","ir":"f_bad"}]},"f_good":{"cap":"A good decision","p":[["No dia seguinte, Helena liga para você. O dono da carta é seu Antônio, um senhor que lê ali todo dia. A carta é da mãe dele, escrita em 1954 e enviada só em 1987. Ele lê tudo em silêncio e chora. Depois segura a sua mão e agradece. Você vai embora com uma sensação boa no peito.","The next day, Helena calls you. The owner of the letter is Mr. Antônio, a man who reads there every day. The letter is from his mother, written in 1954 and only sent in 1987. He reads it all in silence and cries. Then he holds your hand and thanks you. You leave with a good feeling in your chest.",[["No dia seguinte,","The next day,","no|dia|seguinte"],["Helena liga para você.","Helena calls you.","ligar|para|você"],["O dono da carta é seu Antônio,","The owner of the letter is Mr. Antônio,","o|da|carta|ser"],["um senhor que lê ali todo dia.","a man who reads there every day.","um|senhor|que|ler|ali|todo|dia"],["A carta é da mãe dele,","The letter is from his mother,","a|carta|ser|da|mãe|dele"],["escrita em 1954","written in 1954","escrever|em"],["e enviada só em 1987.","and only sent in 1987.","e|enviar|só|em"],["Ele lê tudo em silêncio","He reads it all in silence","ele|ler|tudo|em|silêncio"],["e chora.","and cries.","e|chorar"],["Depois segura a sua mão","Then he holds your hand","depois|a|sua|mão"],["e agradece.","and thanks you.","e|agradecer"],["Você vai embora","You leave","você|ir"],["com uma sensação boa no peito.","with a good feeling in your chest.","com|uma|sensação|bom|no"]]]],"fim":{"tipo":"bom","titulo":"The owner of the letter"}},"f_neutral":{"cap":"Another chance","p":[["Você descobre parte da história, mas não tudo. A carta continua sem nome, mas agora você sabe que alguém procura por ela. Você guarda a carta numa pasta e anota o telefone da biblioteca. Talvez na semana que vem alguém possa ajudar. Nem todo mistério termina no mesmo dia.","You uncover part of the story, but not all of it. The letter still has no name, but now you know that someone is looking for it. You put the letter in a folder and write down the library's phone number. Maybe next week someone can help. Not every mystery ends on the same day.",[["Você descobre parte da história,","You uncover part of the story,","você|descobrir|parte|da|história"],["mas não tudo.","but not all of it.","mas|não|tudo"],["A carta continua sem nome,","The letter still has no name,","a|carta|continuar|sem|nome"],["mas agora você sabe","but now you know","mas|agora|você|saber"],["que alguém procura por ela.","that someone is looking for it.","que|alguém|procurar|por|ela"],["Você guarda a carta numa pasta","You put the letter in a folder","você|guardar|a|carta|em|uma"],["e anota o telefone da biblioteca.","and write down the library's phone number.","e|o|telefone|da|biblioteca"],["Talvez na semana que vem","Maybe next week","talvez|na|semana|que|vir"],["alguém possa ajudar.","someone can help.","alguém|poder|ajudar"],["Nem todo mistério","Not every mystery","nem|todo"],["termina no mesmo dia.","ends on the same day.","terminar|no|mesmo|dia"]]]],"fim":{"tipo":"neutro","titulo":"An open question"}},"f_bad":{"cap":"A hard lesson","p":[["Você age rápido demais e perde um detalhe importante. No meio da confusão, a carta cai da sua bolsa. Quando você percebe, ela não está mais lá. Um funcionário fecha as portas e apaga as luzes. Hoje você não vai encontrar o dono da carta. Às vezes a pressa custa caro.","You act too fast and miss an important detail. In the middle of the confusion, the letter falls out of your bag. When you notice, it's no longer there. A worker closes the doors and turns off the lights. Today you won't find the owner of the letter. Sometimes haste costs you dearly.",[["Você age rápido demais","You act too fast","você|agir|rápido|demais"],["e perde um detalhe importante.","and miss an important detail.","e|perder|um|importante"],["No meio da confusão,","In the middle of the confusion,","no|meio|da"],["a carta cai da sua bolsa.","the letter falls out of your bag.","a|carta|cair|da|sua|bolsa"],["Quando você percebe,","When you notice,","quando|você|perceber"],["ela não está mais lá.","it's no longer there.","ela|não|estar|mais|lá"],["Um funcionário fecha as portas","A worker closes the doors","um|fechar|as|porta"],["e apaga as luzes.","and turns off the lights.","e|as|luz"],["Hoje você não vai encontrar","Today you won't find","hoje|você|não|ir|encontrar"],["o dono da carta.","the owner of the letter.","o|da|carta"],["Às vezes a pressa custa caro.","Sometimes haste costs you dearly.","vez|a|pressa|caro"]]]],"fim":{"tipo":"ruim","titulo":"The lost letter"}}}},{"id":"primeiro-dia","titulo":"The First Day","genero":"Trabalho","nivel":"A1–A2","desc":"A new job in Belo Horizonte, an unfinished report, and a meeting that starts early.","inicio":"c1","cenas":{"c1":{"cap":"The first sign","p":[["É o seu primeiro dia numa empresa de turismo em Belo Horizonte. Você chega ao escritório bem cedo, com um relatório ainda incompleto na bolsa. Perto do elevador, um rapaz parece muito nervoso. Ele conta que a reunião com o diretor começa às nove, uma hora antes do previsto.","It's your first day at a tourism company in Belo Horizonte. You arrive at the office very early, with a still unfinished report in your bag. Near the elevator, a young man looks very nervous. He says the meeting with the director starts at nine, an hour earlier than planned.",[["É o seu primeiro dia","It's your first day","ser|o|seu|primeiro|dia"],["numa empresa de turismo","at a tourism company","em|uma|empresa|de"],["em Belo Horizonte.","in Belo Horizonte.","em"],["Você chega ao escritório bem cedo,","You arrive at the office very early,","você|chegar|ao|escritório|bem|cedo"],["com um relatório ainda incompleto","with a still unfinished report","com|um|relatório|ainda"],["na bolsa.","in your bag.","na|bolsa"],["Perto do elevador,","Near the elevator,","perto|do|elevador"],["um rapaz parece muito nervoso.","a young man looks very nervous.","um|rapaz|parecer|muito"],["Ele conta que a reunião com o diretor","He says the meeting with the director","ele|contar|que|a|reunião|com|o|diretor"],["começa às nove,","starts at nine,","começar"],["uma hora antes do previsto.","an hour earlier than planned.","uma|hora|antes|do"]]]],"escolhas":[{"fl":"Pedir ajuda a uma colega.","pt":"Ask a coworker for help.","ir":"c2a"},{"fl":"Procurar sozinho o que falta no relatório.","pt":"Look on your own for what's missing in the report.","ir":"c2b"}]},"c2a":{"cap":"The conversation","p":[["Você se aproxima de uma colega e se apresenta. Ela se chama Patrícia e cuida das contas da empresa. Escuta com atenção, mas não responde logo. Você explica que o relatório não está pronto. Patrícia olha para a sala do chefe e aponta um corredor à esquerda. Parece que ela sabe de algo.","You go up to a coworker and introduce yourself. Her name is Patrícia, and she handles the company's accounts. She listens carefully, but doesn't answer right away. You explain that the report isn't ready. Patrícia looks toward the boss's office and points to a corridor on the left. It seems she knows something.",[["Você se aproxima de uma colega","You go up to a coworker","você|se|de|uma|colega"],["e se apresenta.","and introduce yourself.","e|se|apresentar"],["Ela se chama Patrícia","Her name is Patrícia","ela|se|chamar"],["e cuida das contas da empresa.","and she handles the company's accounts.","e|cuidar|de|a|conta|da|empresa"],["Escuta com atenção,","She listens carefully,","escutar|com"],["mas não responde logo.","but doesn't answer right away.","mas|não|responder|logo"],["Você explica","You explain","você|explicar"],["que o relatório não está pronto.","that the report isn't ready.","que|o|relatório|não|estar|pronto"],["Patrícia olha para a sala do chefe","Patrícia looks toward the boss's office","olhar|para|a|sala|do|chefe"],["e aponta um corredor à esquerda.","and points to a corridor on the left.","e|um|à|esquerda"],["Parece que ela sabe de algo.","It seems she knows something.","parecer|que|ela|saber|de|algo"]]]],"escolhas":[{"fl":"Escutar Patrícia com atenção.","pt":"Listen carefully to Patrícia.","ir":"c3a"},{"fl":"Agradecer e ir até o corredor.","pt":"Thank her and go to the corridor.","ir":"c3b"}]},"c2b":{"cap":"The team room","p":[["Você decide resolver o problema por conta própria. A sala da equipe ainda está quase vazia. Atrás de uma porta de vidro, você vê uma pasta azul com uma anotação: números de março. Nesse momento, o celular vibra. É uma mensagem do grupo da equipe: alguém perdeu um arquivo importante.","You decide to solve the problem on your own. The team room is still almost empty. Behind a glass door, you see a blue folder with a note: March figures. At that moment, your phone vibrates. It's a message from the team group: someone has lost an important file.",[["Você decide resolver o problema","You decide to solve the problem","você|decidir|o|problema"],["por conta própria.","on your own.","por|conta|próprio"],["A sala da equipe","The team room","a|sala|da|equipe"],["ainda está quase vazia.","is still almost empty.","ainda|estar|quase|vazio"],["Atrás de uma porta de vidro,","Behind a glass door,","de|uma|porta|de|vidro"],["você vê uma pasta azul","you see a blue folder","você|ver|uma|azul"],["com uma anotação: números de março.","with a note: March figures.","com|uma|número|de"],["Nesse momento,","At that moment,","em|esse|momento"],["o celular vibra.","your phone vibrates.","o|celular"],["É uma mensagem do grupo da equipe:","It's a message from the team group:","ser|uma|mensagem|do|grupo|da|equipe"],["alguém perdeu um arquivo importante.","someone has lost an important file.","alguém|perder|um|importante"]]]],"escolhas":[{"fl":"Abrir a porta e olhar a pasta azul.","pt":"Open the door and look at the blue folder.","ir":"c3c"},{"fl":"Responder à mensagem do grupo.","pt":"Reply to the group message.","ir":"c3d"}]},"c3a":{"cap":"The hidden paper","p":[["Patrícia pega um papel pequeno na mesa e mostra para você. Nele está escrito o nome de um arquivo e uma senha. Ela explica que existe uma cópia do relatório antigo no computador da equipe. Com esses números, você pode terminar o seu em meia hora. Mas ela pede uma coisa: não contar nada ao chefe.","Patrícia picks up a small piece of paper from the desk and shows it to you. Written on it are the name of a file and a password. She explains there's a copy of the old report on the team computer. With those figures, you can finish yours in half an hour. But she asks for one thing: not to tell the boss anything.",[["Patrícia pega um papel pequeno","Patrícia picks up a small piece of paper","pegar|um|papel|pequeno"],["na mesa","from the desk","na|mesa"],["e mostra para você.","and shows it to you.","e|mostrar|para|você"],["Nele está escrito","Written on it are","em|ele|estar|escrever"],["o nome de um arquivo e uma senha.","the name of a file and a password.","o|nome|de|um|e|uma"],["Ela explica que existe uma cópia","She explains there's a copy","ela|explicar|que|uma"],["do relatório antigo","of the old report","do|relatório"],["no computador da equipe.","on the team computer.","no|computador|da|equipe"],["Com esses números,","With those figures,","com|esse|número"],["você pode terminar o seu em meia hora.","you can finish yours in half an hour.","você|poder|terminar|o|seu|em|meio|hora"],["Mas ela pede uma coisa:","But she asks for one thing:","mas|ela|pedir|uma|coisa"],["não contar nada ao chefe.","not to tell the boss anything.","não|contar|nada|ao|chefe"]]]],"escolhas":[{"fl":"Aceitar a ajuda e conferir os números.","pt":"Accept the help and check the figures.","ir":"f_good"},{"fl":"Usar só uma parte dos números.","pt":"Use only part of the figures.","ir":"f_neutral"}]},"c3b":{"cap":"The closed door","p":[["Você agradece e entra no corredor. Ele termina numa porta fechada, com o nome do diretor. Do outro lado, você ouve vozes. Alguém fala de uma pasta azul e de números errados no relatório do mês passado. Você para e presta atenção. Faltam vinte minutos para a reunião.","You thank her and go into the corridor. It ends at a closed door with the director's name on it. On the other side, you hear voices. Someone talks about a blue folder and about wrong figures in last month's report. You stop and pay attention. There are twenty minutes left before the meeting.",[["Você agradece","You thank her","você|agradecer"],["e entra no corredor.","and go into the corridor.","e|entrar|no"],["Ele termina numa porta fechada,","It ends at a closed door,","ele|terminar|em|uma|porta|fechar"],["com o nome do diretor.","with the director's name on it.","com|o|nome|do|diretor"],["Do outro lado,","On the other side,","do|outro|lado"],["você ouve vozes.","you hear voices.","você|ouvir|voz"],["Alguém fala de uma pasta azul","Someone talks about a blue folder","alguém|falar|de|uma|azul"],["e de números errados","and about wrong figures","e|de|número|errado"],["no relatório do mês passado.","in last month's report.","no|relatório|do|mês|passado"],["Você para e presta atenção.","You stop and pay attention.","você|parar|e"],["Faltam vinte minutos","There are twenty minutes left","minuto"],["para a reunião.","before the meeting.","para|a|reunião"]]]],"escolhas":[{"fl":"Esperar e escutar perto da porta.","pt":"Wait and listen by the door.","ir":"f_neutral"},{"fl":"Bater na porta e se apresentar ao diretor.","pt":"Knock and introduce yourself to the director.","ir":"f_bad"}]},"c3c":{"cap":"Someone knows","p":[["Você abre a porta de vidro e pega a pasta azul. Dentro dela, há uma tabela com os números que faltam no seu relatório. Ao lado da janela aberta, uma senhora toma café e olha para você. É dona Lúcia, a gerente da equipe. Ela pergunta, séria, o que você está fazendo com aquela pasta.","You open the glass door and pick up the blue folder. Inside, there's a table with the figures missing from your report. Next to the open window, a woman is drinking coffee and looking at you. It's Dona Lúcia, the team manager. She asks, seriously, what you are doing with that folder.",[["Você abre a porta de vidro","You open the glass door","você|abrir|a|porta|de|vidro"],["e pega a pasta azul.","and pick up the blue folder.","e|pegar|a|azul"],["Dentro dela, há uma tabela","Inside, there's a table","dentro|dela|haver|uma"],["com os números que faltam","with the figures missing","com|os|número|que"],["no seu relatório.","from your report.","no|seu|relatório"],["Ao lado da janela aberta,","Next to the open window,","ao|lado|da|janela|aberto"],["uma senhora toma café","a woman is drinking coffee","uma|senhora|tomar|café"],["e olha para você.","and looking at you.","e|olhar|para|você"],["É dona Lúcia, a gerente da equipe.","It's Dona Lúcia, the team manager.","ser|a|da|equipe"],["Ela pergunta, séria,","She asks, seriously,","ela|perguntar|sério"],["o que você está fazendo","what you are doing","o|que|você|estar|fazer"],["com aquela pasta.","with that folder.","com|aquele"]]]],"escolhas":[{"fl":"Dizer a verdade e pedir ajuda.","pt":"Tell the truth and ask for help.","ir":"f_good"},{"fl":"Devolver a pasta e sair sem explicar.","pt":"Hand back the folder and leave without explaining.","ir":"f_bad"}]},"c3d":{"cap":"The message","p":[["Você lê a mensagem mais uma vez. O arquivo perdido é justamente a tabela que falta no seu relatório. Por um momento, você pensa em desistir e pedir para remarcar a reunião. Mas é o seu primeiro dia, e você quer causar uma boa impressão. Você ainda quer apresentar o relatório às nove.","You read the message one more time. The lost file is exactly the table that's missing from your report. For a moment, you think about giving up and asking to reschedule the meeting. But it's your first day, and you want to make a good impression. You still want to present the report at nine.",[["Você lê a mensagem","You read the message","você|ler|a|mensagem"],["mais uma vez.","one more time.","mais|uma|vez"],["O arquivo perdido","The lost file","o|perder"],["é justamente a tabela","is exactly the table","ser|a"],["que falta no seu relatório.","that's missing from your report.","que|no|seu|relatório"],["Por um momento,","For a moment,","por|um|momento"],["você pensa em desistir","you think about giving up","você|pensar|em"],["e pedir para remarcar a reunião.","and asking to reschedule the meeting.","e|pedir|para|a|reunião"],["Mas é o seu primeiro dia,","But it's your first day,","mas|ser|o|seu|primeiro|dia"],["e você quer causar uma boa impressão.","and you want to make a good impression.","e|você|querer|uma|bom|impressão"],["Você ainda quer apresentar o relatório às nove.","You still want to present the report at nine.","você|ainda|querer|apresentar|o|relatório"]]]],"escolhas":[{"fl":"Parar e preparar outro plano.","pt":"Stop and prepare another plan.","ir":"f_neutral"},{"fl":"Inventar os números que faltam.","pt":"Make up the missing figures.","ir":"f_bad"}]},"f_good":{"cap":"A good decision","p":[["Você decide pedir ajuda e agir rápido. Com os números certos, você termina o relatório a tempo. Na reunião, você explica cada parte com calma, e o diretor faz perguntas difíceis. No final, ele sorri e diz que o trabalho está ótimo. No primeiro dia, você aprendeu que fazer perguntas não é fraqueza.","You decide to ask for help and act fast. With the right figures, you finish the report on time. In the meeting, you explain each part calmly, and the director asks hard questions. In the end, he smiles and says the work is great. On your first day, you learned that asking questions isn't weakness.",[["Você decide pedir ajuda","You decide to ask for help","você|decidir|pedir|ajuda"],["e agir rápido.","and act fast.","e|agir|rápido"],["Com os números certos,","With the right figures,","com|os|número|certo"],["você termina o relatório a tempo.","you finish the report on time.","você|terminar|o|relatório|a|tempo"],["Na reunião,","In the meeting,","na|reunião"],["você explica cada parte com calma,","you explain each part calmly,","você|explicar|cada|parte|com|calmo"],["e o diretor faz perguntas difíceis.","and the director asks hard questions.","e|o|diretor|fazer|pergunta|difícil"],["No final, ele sorri","In the end, he smiles","no|final|ele|sorrir"],["e diz que o trabalho está ótimo.","and says the work is great.","e|dizer|que|o|trabalho|estar|ótimo"],["No primeiro dia,","On your first day,","no|primeiro|dia"],["você aprendeu","you learned","você|aprender"],["que fazer perguntas não é fraqueza.","that asking questions isn't weakness.","que|fazer|pergunta|não|ser"]]]],"fim":{"tipo":"bom","titulo":"A great start"}},"f_neutral":{"cap":"Another chance","p":[["Você apresenta parte do relatório, mas não tudo. O diretor percebe que faltam alguns números e fica sério. Mesmo assim, ele aceita a explicação e dá mais dois dias para você terminar. A situação está mais tranquila do que antes. Não foi perfeito, mas é só o começo.","You present part of the report, but not all of it. The director notices that some figures are missing and turns serious. Even so, he accepts the explanation and gives you two more days to finish. The situation is calmer than before. It wasn't perfect, but it's only the beginning.",[["Você apresenta parte do relatório,","You present part of the report,","você|apresentar|parte|do|relatório"],["mas não tudo.","but not all of it.","mas|não|tudo"],["O diretor percebe","The director notices","o|diretor|perceber"],["que faltam alguns números","that some figures are missing","que|algum|número"],["e fica sério.","and turns serious.","e|ficar|sério"],["Mesmo assim,","Even so,","mesmo|assim"],["ele aceita a explicação","he accepts the explanation","ele|aceitar|a"],["e dá mais dois dias","and gives you two more days","e|dar|mais|dia"],["para você terminar.","to finish.","para|você|terminar"],["A situação está mais tranquila","The situation is calmer","a|situação|estar|mais"],["do que antes.","than before.","do|que|antes"],["Não foi perfeito,","It wasn't perfect,","não|ser|perfeito"],["mas é só o começo.","but it's only the beginning.","mas|ser|só|o|começo"]]]],"fim":{"tipo":"neutro","titulo":"Half done"}},"f_bad":{"cap":"A hard lesson","p":[["Você decide rápido demais e perde um detalhe importante. Na reunião, o diretor encontra um erro grave no seu relatório, logo na primeira página. Todo mundo fica em silêncio. Mais tarde, a gerente chama você para uma conversa. Hoje não foi um bom começo, mas agora você sabe o que conferir da próxima vez.","You decide too fast and miss an important detail. In the meeting, the director finds a serious mistake in your report, right on the first page. Everyone goes silent. Later, the manager calls you in for a talk. Today wasn't a good start, but now you know what to check next time.",[["Você decide rápido demais","You decide too fast","você|decidir|rápido|demais"],["e perde um detalhe importante.","and miss an important detail.","e|perder|um|importante"],["Na reunião, o diretor encontra","In the meeting, the director finds","na|reunião|o|diretor|encontrar"],["um erro grave no seu relatório,","a serious mistake in your report,","um|erro|no|seu|relatório"],["logo na primeira página.","right on the first page.","logo|na|primeiro|página"],["Todo mundo fica em silêncio.","Everyone goes silent.","todo|mundo|ficar|em|silêncio"],["Mais tarde, a gerente","Later, the manager","mais|tarde|a"],["chama você para uma conversa.","calls you in for a talk.","chamar|você|para|uma|conversa"],["Hoje não foi um bom começo,","Today wasn't a good start,","hoje|não|ser|um|bom|começo"],["mas agora você sabe","but now you know","mas|agora|você|saber"],["o que conferir da próxima vez.","what to check next time.","o|que|da|próximo|vez"]]]],"fim":{"tipo":"ruim","titulo":"A bad first impression"}}}}];
